// Order Confirmation Entry
const ctx = $input.item.json;
return [{ json: {
    ...ctx
} }];

// Build context for checkout AI
const ctx = $('Order Confirmation Entry').item.json;

// The parent workflow (01_incoming_message_router) already passed historyText
// inside ctx. We don't need to overwrite it. Just pass ctx along.

return [{ json: {
    ...ctx
} }];

// Parse the AI Agent delivery info response
let raw = '';
if (typeof $input.item.json === 'string') raw = $input.item.json;
else if ($input.item.json && typeof $input.item.json.text === 'string') raw = $input.item.json.text;
else if ($input.item.json && typeof $input.item.json.output === 'string') raw = $input.item.json.output;
else raw = JSON.stringify($input.item.json || {});

const ctx = $('Build Checkout Context').item.json;
const userMsg = (ctx.messageText || '').trim();

let has_delivery = false;
let address = null;
let payment = 'cash_on_delivery';
let customer_name = null;
let customer_mobile = null;
let items = [];
let total_price = 0;

try {
    const jsonMatch = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    const jsonStr = jsonMatch ? jsonMatch[1] : raw;
    const match = jsonStr.match(/\{[\s\S]*\}/);
    if (match) {
        let result = JSON.parse(match[0]);
        if (result.action_input && typeof result.action_input === 'string') {
            result = JSON.parse(result.action_input.match(/\{[\s\S]*\}/)[0]);
        }
        if (result.has_delivery_info === true || result.has_delivery_info === "true") has_delivery = true;
        if (result.delivery_address && result.delivery_address !== 'null' && result.delivery_address !== 'Provided in chat') address = result.delivery_address;
        if (result.payment_method) payment = result.payment_method;
        if (result.customer_name && result.customer_name !== 'null') customer_name = result.customer_name;
        if (result.customer_mobile && result.customer_mobile !== 'null') customer_mobile = result.customer_mobile;
        if (result.items) items = result.items;
        if (result.total_price) {
            let tp = parseFloat(String(result.total_price).replace(/,/g, ''));
            if (!isNaN(tp)) total_price = tp;
        }
    }
} catch(e) {}

// Fallback: parse comma or newline separated user text directly (e.g. "Name, Address, Payment")
if (userMsg && (!address || !customer_name)) {
    const parts = userMsg.split(/[\n,]+/).map(p => p.trim()).filter(Boolean);
    if (parts.length >= 2) {
        has_delivery = true;
        if (!customer_name) customer_name = parts[0];

        for (let i = 1; i < parts.length; i++) {
            const p = parts[i];
            const pLower = p.toLowerCase();
            if (pLower.includes('cash') || pLower.includes('cod')) {
                payment = 'cash_on_delivery';
            } else if (pLower.includes('bank') || pLower.includes('transfer')) {
                payment = 'bank_transfer';
            } else if (/^07\d{8}$|^\d{10}$/.test(p.replace(/\s+/g, ''))) {
                if (!customer_mobile) customer_mobile = p;
            } else if (!address) {
                address = p;
            }
        }
    }
}

// Fallback for customer_mobile from WhatsApp phoneNumber metadata
if (!customer_mobile && ctx.phoneNumber) {
    customer_mobile = ctx.phoneNumber.replace(/@.*/, '');
}
if (!address && has_delivery) {
    address = 'Provided in chat';
}

return [{ json: {
    ...ctx,
    has_delivery_info: has_delivery,
    delivery_address: address,
    payment_method: payment,
    customer_name: customer_name || 'Customer',
    customer_mobile: customer_mobile || 'Provided',
    items: items,
    total_price: total_price
} }];

// Build the order object with delivery details
const ctx = $('Parse Delivery Info').item.json;

let itemsArray = (ctx.items && Array.isArray(ctx.items) && ctx.items.length > 0) 
  ? ctx.items 
  : [{ product_name: 'Order from chat', qty: 1, unit_price: 0 }];

let tp = parseFloat(ctx.total_price) || 0;
if (tp > 0 && tp < 1000) tp = tp * 300;

// Scan all messages in Fetch Chat History to find the quoted price and product name
let allChat = [];
try {
    allChat = $('Fetch Chat History').all().map(i => i.json.message_text || '');
} catch(e) {}

let foundPrice = 0;
let foundProduct = '';

for (let msg of allChat) {
    if (!foundPrice) {
        // Look for prices like "LKR 3,000", "LKR 3000", "LKR 4,500", "LKR 2,400"
        const pMatch = msg.match(/LKR\s*([\d,]+)/i);
        if (pMatch) {
            const num = parseFloat(pMatch[1].replace(/,/g, ''));
            if (num > 0 && num !== 350) { // skip delivery fee
                foundPrice = num;
            }
        }
    }
    if (!foundProduct) {
        const products = [
            'Premium Cotton T-Shirt',
            'Polo T-Shirt',
            'V-Neck T-Shirt',
            'Cotton Bucket Hat',
            'Floral Midi Dress',
            'Casual Shirt Dress',
            'Denim Jacket',
            'Bomber Jacket',
            'Slim-Fit Chinos',
            'Formal Dress Trousers',
            'Canvas Tote Bag',
            'Evening Gown'
        ];
        for (let p of products) {
            if (msg.toLowerCase().includes(p.toLowerCase())) {
                foundProduct = p;
                break;
            }
        }
    }
}

if (tp === 0 && foundPrice > 0) {
    tp = foundPrice;
}

// Calculate unit prices and assign product names
const totalQty = itemsArray.reduce((sum, item) => sum + (parseInt(item.qty) || 1), 0) || 1;

for (let i of itemsArray) {
    let up = parseFloat(i.unit_price) || 0;
    if (up > 0 && up < 1000) up = up * 300;
    if (up === 0 && tp > 0) {
        up = Math.round(tp / totalQty);
    }
    i.unit_price = up;

    // Improve product name if it only contains variant/size/color info
    let pName = (i.product_name || '').trim();
    if (foundProduct) {
        if (!pName || pName === 'Order from chat' || pName.toLowerCase().includes('size') || pName.toLowerCase().includes('color') || !pName.toLowerCase().includes(foundProduct.toLowerCase())) {
            i.product_name = pName ? (foundProduct + ' (' + pName + ')') : foundProduct;
        }
    }
}

// Recompute total price from items
tp = itemsArray.reduce((sum, item) => sum + ((item.unit_price || 0) * (parseInt(item.qty) || 1)), 0);

return [{ json: {
    ...ctx,
    items: JSON.stringify(itemsArray),
    items_array: itemsArray,
    total_price: tp,
    discount_applied: 0.00,
    status: 'confirmed'
} }];
